css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-ms{width:min(1060px,100%);display:grid;gap:1.6em}
.fx-ms h2{font-size:clamp(1.8em,4vw,2.6em)}
.fx-ms .cols{column-count:3;column-gap:1.1em}
.fx-ms figure{margin:0 0 1.1em;break-inside:avoid;position:relative;border-radius:var(--radius);overflow:hidden;transition:transform calc(.4s/var(--speed)) ease,box-shadow calc(.4s/var(--speed)) ease}
.fx-ms .fx-art{aspect-ratio:var(--r)}
.fx-ms figcaption{position:absolute;left:.7em;bottom:.7em;padding:.35em .8em;border-radius:99px;font-size:.78em;font-weight:700;background:var(--surface);color:var(--text);opacity:0;transform:translateY(6px);transition:opacity calc(.3s/var(--speed)),transform calc(.3s/var(--speed))}
.fx-ms figure:hover{transform:translateY(-4px);box-shadow:0 22px 34px -22px color-mix(in srgb,var(--text) 60%,transparent)}
.fx-ms figure:hover figcaption{opacity:1;transform:none}
@media(max-width:820px){.fx-ms .cols{column-count:2}}
@media(max-width:420px){.fx-ms .cols{column-gap:.7em}.fx-ms figure{margin-bottom:.7em}}
@media(prefers-reduced-motion:reduce){.fx-ms figure,.fx-ms figcaption{transition:none}.fx-ms figure:hover{transform:none}
.fx-ms figure.is-tap{transform:none}}
/* touch: :hover mirrored as .is-tap */
.fx-ms figure.is-tap{transform:translateY(-4px);box-shadow:0 22px 34px -22px color-mix(in srgb,var(--text) 60%,transparent)}
.fx-ms figure.is-tap figcaption{opacity:1;transform:none}
